import { test, expect, Page } from '@playwright/test';

test.describe('Payment Timeout Error Handling', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/checkout');
  });

  test('should redirect to error page when payment times out', async () => {
    // Fill in payment form
    await page.getByLabel('Card Number').fill('4242424242424242');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVC').fill('123');
    await page.getByLabel('Cardholder Name').fill('John Doe');

    // Simulate timeout by intercepting the payment request
    await page.route('**/api/payment/process', route => {
      setTimeout(() => {
        route.abort('timedout');
      }, 100);
    });

    // Click submit button
    await page.getByRole('button', { name: /complete payment/i }).click();

    // Wait for redirect to error page
    await page.waitForURL('**/error/payment-timeout', { timeout: 10000 });

    // Verify error page content
    expect(page.url()).toContain('/error/payment-timeout');
    await expect(page.getByRole('heading', { name: /payment timeout/i })).toBeVisible();
    await expect(page.getByText(/your payment request timed out/i)).toBeVisible();
  });

  test('should display retry button on timeout error page', async () => {
    // Navigate directly to error page for testing
    await page.goto('http://localhost:3000/error/payment-timeout');

    // Verify error page is displayed
    await expect(page.getByRole('heading', { name: /payment timeout/i })).toBeVisible();

    // Verify retry button is present and clickable
    const retryButton = page.getByRole('button', { name: /try again/i });
    await expect(retryButton).toBeVisible();
    await expect(retryButton).toBeEnabled();

    // Click retry button
    await retryButton.click();

    // Verify redirect back to checkout page
    await page.waitForURL('**/checkout', { timeout: 5000 });
    expect(page.url()).toContain('/checkout');
  });

  test('should show error message with timeout details', async () => {
    // Navigate to error page
    await page.goto('http://localhost:3000/error/payment-timeout');

    // Verify error message is visible
    const errorMessage = page.getByText(/your payment request timed out/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details section
    const errorDetails = page.getByRole('region', { name: /error details/i });
    await expect(errorDetails).toBeVisible();

    // Verify support contact information
    await expect(page.getByText(/contact support/i)).toBeVisible();
    await expect(page.getByRole('link', { name: /support@example.com/i })).toBeVisible();
  });

  test('should handle multiple timeout attempts gracefully', async () => {
    // Fill in payment form
    await page.getByLabel('Card Number').fill('4242424242424242');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVC').fill('123');
    await page.getByLabel('Cardholder Name').fill('Jane Doe');

    // Simulate timeout on first attempt
    await page.route('**/api/payment/process', route => {
      setTimeout(() => {
        route.abort('timedout');
      }, 100);
    });

    // First payment attempt
    await page.getByRole('button', { name: /complete payment/i }).click();
    await page.waitForURL('**/error/payment-timeout', { timeout: 10000 });

    // Click retry button
    await page.getByRole('button', { name: /try again/i }).click();
    await page.waitForURL('**/checkout', { timeout: 5000 });

    // Verify form is still populated
    await expect(page.getByLabel('Card Number')).toHaveValue('4242424242424242');
    await expect(page.getByLabel('Cardholder Name')).toHaveValue('Jane Doe');

    // Verify retry counter or attempt indicator
    const attemptIndicator = page.getByText(/attempt \d+ of \d+/i);
    if (await attemptIndicator.isVisible()) {
      await expect(attemptIndicator).toBeVisible();
    }
  });
});
